INSERT INTO reviews (id, title, release_year, poster, trailer_url, content, author_id, created_at) VALUES
  (1, 'Крёстный отец', 1972, 'godfather.jpg', 'https://www.youtube.com/watch?v=sY1S34973zA', 'Сага о семье Корлеоне — это не столько фильм о мафии, сколько история о власти, верности и цене, которую за них приходится платить.

Марлон Брандо создал образ дона Вито, который невозможно забыть, а Аль Пачино за три часа проходит путь от тихого героя войны до холодного главы клана. Каждая сцена выверена до мелочей: свет, музыка Нино Роты, паузы между репликами.

Фильм, после которого понимаешь, почему его десятилетиями называют одним из лучших в истории кино.', 1, '2025-08-01 12:00:00'),
  (2, 'Тёмный рыцарь', 2008, 'dark-knight.jpg', 'https://www.youtube.com/watch?v=EXeTwQWrcwY', 'Кристофер Нолан снял не комикс, а напряжённый криминальный триллер, в котором Готэм похож на любой большой город.

Главное событие фильма — Джокер Хита Леджера. Он не просто злодей, а воплощение хаоса, и каждое его появление держит в напряжении. Бэтмен здесь впервые по-настоящему сомневается в том, что делает.

Фильм задаёт неудобные вопросы о границах справедливости и о том, чем приходится жертвовать ради порядка.', 1, '2025-08-02 12:00:00'),
  (3, 'Начало', 2010, 'inception.jpg', 'https://www.youtube.com/watch?v=YoHD9XEInc0', 'Фильм-головоломка о людях, которые умеют проникать в чужие сны и красть идеи. Или, что гораздо сложнее, внедрять их.

Нолан выстраивает многоуровневый сюжет, где каждый слой сна живёт по своим законам времени, а финальная сцена с волчком до сих пор вызывает споры. Музыка Ханса Циммера превращает просмотр почти в физическое ощущение.

Это кино, которое хочется пересматривать, чтобы замечать новые детали.', 1, '2025-08-03 12:00:00'),
  (4, 'Бойцовский клуб', 1999, 'fight-club.jpg', 'https://www.youtube.com/watch?v=SUXWAEX2jlg', 'История офисного клерка, страдающего бессонницей, превращается в злую сатиру на общество потребления.

Эдвард Нортон и Брэд Питт играют дуэт, за которым интересно следить до самого конца, а неожиданная развязка заставляет мысленно пересмотреть весь фильм заново. Финчер снимает мрачно, дерзко и с чёрным юмором.

Фильм, который спустя годы не потерял остроты.', 1, '2025-08-04 12:00:00'),
  (5, 'Криминальное чтиво', 1994, 'pulp-fiction.jpg', 'https://www.youtube.com/watch?v=s7EdQ4FqbhY', 'Несколько историй из жизни гангстеров, боксёра и пары грабителей, рассказанных не по порядку, но складывающихся в единую картину.

Тарантино превращает обычные разговоры в главное украшение фильма: диалоги о бургерах запоминаются не хуже перестрелок. Танец Траволты и Турман давно стал частью поп-культуры.

Смелый, ироничный и невероятно стильный фильм, который изменил независимое кино девяностых.', 1, '2025-08-05 12:00:00'),
  (6, 'Матрица', 1999, 'matrix.jpg', 'https://www.youtube.com/watch?v=vKQi3bBA1y8', 'Хакер Нео узнаёт, что привычный мир — всего лишь компьютерная симуляция, а люди давно живут в плену у машин.

Вачовски соединили философию, киберпанк и восточные единоборства, а эффект замедленного времени потом копировали годами. Красная или синяя таблетка — вопрос, который стал крылатым.

Фильм, после которого невольно начинаешь сомневаться в реальности происходящего вокруг.', 1, '2025-08-06 12:00:00'),
  (7, 'Леон', 1994, 'leon.jpg', 'https://www.youtube.com/watch?v=jawVxq1Iyl0', 'Наёмный убийца Леон живёт по строгим правилам, пока в его жизни не появляется двенадцатилетняя Матильда, потерявшая семью.

Жан Рено играет молчаливого и неожиданно трогательного героя, Натали Портман в своей первой большой роли держится на равных со взрослыми актёрами, а Гэри Олдман создаёт одного из самых пугающих злодеев девяностых.

Жёсткий боевик, который на самом деле оказывается историей о дружбе и одиночестве.', 1, '2025-08-07 12:00:00'),
  (8, 'Гладиатор', 2000, 'gladiator.jpg', 'https://www.youtube.com/watch?v=P5ieIbInFpg', 'Римский полководец Максимус теряет семью и свободу, но продолжает бороться — теперь уже на арене.

Ридли Скотт возродил жанр исторического эпоса: масштабные битвы, Колизей, полный зрителей, и Рассел Кроу в роли, за которую он получил «Оскар». Хоакин Феникс убедительно играет слабого и жестокого императора Коммода.

Фильм о чести и мести, финал которого трогает до слёз.', 1, '2025-08-08 12:00:00'),
  (9, 'Король Лев', 1994, 'lion-king.jpg', 'https://www.youtube.com/watch?v=lFzVJEksoDY', 'Мультфильм о львёнке Симбе, который после гибели отца убегает из дома и должен найти в себе силы вернуться.

История рассказана так, что понятна и детям, и взрослым. Песни Элтона Джона и музыка Ханса Циммера, Тимон и Пумба с их «Акуна матата» — всё это давно стало классикой.

Один из лучших мультфильмов Disney, который совсем не стареет.', 1, '2025-08-09 12:00:00'),
  (10, 'Назад в будущее', 1985, 'back-to-the-future.jpg', 'https://www.youtube.com/watch?v=qvsgGtivCgs', 'Подросток Марти Макфлай на машине времени, собранной из DeLorean, попадает в 1955 год и случайно мешает знакомству собственных родителей.

Роберт Земекис соединил фантастику, комедию и приключения в идеально выстроенный сюжет, где каждая мелочь из первой половины выстреливает во второй. Дуэт Майкла Дж. Фокса и Кристофера Ллойда невероятно обаятелен.

Лёгкий и умный фильм, который одинаково нравится всем поколениям.', 1, '2025-08-10 12:00:00'),
  (11, 'Тайна Коко', 2017, 'coco.jpg', 'https://www.youtube.com/watch?v=Rvr68u6k5sI', 'Яркий мультфильм о памяти и семье.

Мальчик Мигель мечтает стать музыкантом, хотя в его семье музыка под запретом, и случайно попадает в Страну мёртвых. Картинка очень красивая, а музыка запоминается с первого раза.

Это добрая история о том, что нужно помнить близких, и о праве заниматься тем, что любишь. Подойдёт и детям, и взрослым.', 1, '2025-08-15 10:00:00'),
  (12, 'Интерстеллар', 2014, 'interstellar.jpg', 'https://www.youtube.com/watch?v=zSWdZVtXT7E', 'Фантастика, где главное это человеческие отношения.

Кристофер Нолан снимает большое космическое путешествие, но в центре остаётся история отца и дочери. Музыка Ханса Циммера и образ чёрной дыры создают ощущение, что смотришь что-то по-настоящему масштабное.

Фильм требует внимания: некоторые сцены трудно понять с первого раза. Зато после просмотра хочется обсуждать его и пересматривать.', 1, '2025-08-15 11:00:00'),
  (13, '1+1', 2011, 'intouchables.jpg', 'https://www.youtube.com/watch?v=34WIbmXkewU', 'Комедия, после которой остаётся тёплое чувство.

История дружбы аристократа, прикованного к инвалидному креслу, и его нового помощника из пригорода. Франсуа Клюзе и Омар Си играют так естественно, что за их общением наблюдаешь, как за настоящей дружбой.

Фильм смешной, но не пустой: в нём есть и грусть, и честный разговор о том, как люди относятся друг к другу. Его легко рекомендовать любому.', 1, '2025-08-15 12:00:00'),
  (14, 'Властелин колец: Две крепости', 2002, 'lotr-towers.jpg', 'https://www.youtube.com/watch?v=hYcw5ksV8YQ', 'Самая тёмная и напряжённая часть трилогии.

Братство разделено, и фильм следит сразу за несколькими линиями: путь Фродо и Сэма с Горлумом, дорога Арагорна, Леголаса и Гимли, битва за Хельмову Падь. Сражение у крепости остаётся одним из лучших в жанре.

Горлум в этой части особенно удался: ему сочувствуешь и одновременно опасаешься его. Середина трилогии, которая нисколько не проседает.', 1, '2025-08-15 13:00:00'),
  (15, 'Властелин колец: Братство Кольца', 2001, 'lotr-fellowship.jpg', 'https://www.youtube.com/watch?v=V75dMMIW2B4', 'С этого фильма началось путешествие, которое хочется повторить.

Первая часть трилогии знакомит со Средиземьем и собирает Братство Кольца. Пейзажи Новой Зеландии, музыка Говарда Шора и бережная работа с книгой создают ощущение настоящего мира, в который быстро погружаешься.

Здесь меньше битв, чем в продолжениях, зато больше атмосферы. Отличное начало, после которого сразу тянет включить вторую часть.', 1, '2025-08-15 14:00:00'),
  (16, 'Властелин колец: Возвращение короля', 2003, 'lotr-return.jpg', 'https://www.youtube.com/watch?v=r5X-hFf6Bwo', 'Достойное завершение большой саги.

Последняя часть трилогии собирает всё, что было выстроено в первых двух: битву за Минас Тирит, путь Фродо и Сэма к Роковой горе и прощание героев. Масштаб огромный, но личные истории не теряются на фоне сражений.

Фильм получил одиннадцать «Оскаров», и это не удивляет. Финал длинный, но оставляет ощущение, что история действительно закончена.', 1, '2025-08-15 15:00:00'),
  (17, 'Форрест Гамп', 1994, 'forrest-gump.jpg', 'https://www.youtube.com/watch?v=bLvqoHBptjg', 'Фильм про доброту, верность и умение не сдаваться.

Простой человек проходит через десятилетия американской истории, и каждый эпизод становится маленькой историей про любовь, дружбу и потерю. Том Хэнкс играет так, что Форресту веришь с первой минуты.

Местами фильм наивный, но эта наивность и делает его тёплым. Хорошая картина на вечер, когда хочется доброй истории.', 1, '2025-08-15 16:00:00'),
  (18, 'Побег из Шоушенка', 1994, 'shawshank.jpg', 'https://www.youtube.com/watch?v=PLl99DlL6b4', 'Фильм о том, как надежда помогает пережить годы за решёткой.

Тюремная драма без громких эффектов: здесь важны неспешный рассказ, дружба двух заключённых и ощущение времени, которое тянется годами. Тим Роббинс и Морган Фриман играют так, что в каждом взгляде есть история.

Финал одновременно тёплый и неожиданный. Фильм, который не надоедает пересматривать.', 1, '2025-08-15 17:00:00'),
  (19, 'Список Шиндлера', 1993, 'schindlers-list.jpg', 'https://www.youtube.com/watch?v=gG22XNhtnoY', 'История о том, что даже в самое тёмное время остаётся место человеческому выбору.

Фильм снят в чёрно-белом цвете, и это не стилизация: так история выглядит строже и честнее. Камера почти не отводит взгляд, но и не давит на зрителя, всё держится на актёрах и точных деталях. Лиам Нисон и Рэйф Файнс играют двух людей, которые стоят по разные стороны одного и того же ужаса.

Три часа проходят без ощущения затянутости. После финала хочется помолчать, а не обсуждать. Это тот случай, когда фильм нужно посмотреть хотя бы один раз.', 1, '2025-08-15 18:00:00'),
  (20, 'Зеленая миля', 1999, 'green-mile.jpg', 'https://www.youtube.com/watch?v=Ki4haFrqSrw', '«Они помогли ему убить себя и так происходит каждый день во всем мире»...

Фильм, который я могу смело назвать шедевром. Фильм, который длится три часа и которые пролетают незаметно. Фильм, который смотрится каждый раз как в первый. Фильм, который нельзя забыть и которым нельзя не проникнуться. Фильм, котрый заставляет задуматься о жизни, которую мы тратим на пустяки, теша себя иллюзией бессмертия, о смерти, которая не щадит никого.

Фильм о зле, которое не всегда наказуемо и о добре, которое подчас бессильно что-либо изменить. И тебе остается лишь смотреть на то, как вершится суд, над тем кто не должен сидеть на скамье подсудимых.

Фильм, который изменил мое мировоззрение и научил по-другому относиться к жизни.', 1, '2025-08-15 19:00:00');

INSERT INTO comments (review_id, user_id, text, created_at) VALUES
  (2, 4, 'Джокер Леджера — лучший злодей в истории кино.', '2025-08-05 19:00:00'),
  (10, 2, 'Смотрел в детстве и пересматриваю с детьми, им тоже нравится.', '2025-08-12 17:20:00'),
  (12, 3, 'Нолан в очередной раз удивил, смотрел с замиранием сердца.', '2025-08-18 22:10:00'),
  (18, 3, 'Лучший фильм, который я видел. Пересматриваю каждый год.', '2025-08-16 18:00:00'),
  (18, 4, 'Согласен, концовка пробирает до мурашек.', '2025-08-17 09:15:00'),
  (19, 2, 'Музыка и операторская работа просто невероятные.', '2025-08-16 20:40:00'),
  (20, 2, 'Имя, не нуждающееся в представлении. Человек, выдумавший уйму увлекательных сюжетов, создавший прекрасные и загадочные миры, отличающиеся мрачностью и таинственностью.', '2025-08-16 10:30:00'),
  (20, 3, 'С экранизациями собственных романов Кингу всегда не везло. Большинство режиссёров предпочитало снимать, опираясь на своё видение сюжета, тогда как исключительная кинговская атмосфера пропадала.', '2025-08-17 11:30:00'),
  (20, 4, 'Либо режиссёр пытался наворотить кучу спецэффектов, и получалась ерунда («Ловец снов»), либо режиссёр всё переиначивал на свой лад, и творился ад кромешный в сценарном плане («Сияние» Кубрика, кстати говоря, та же беда', '2025-08-18 12:30:00'),
  (20, 2, 'Имя, не нуждающееся в представлении. Человек, выдумавший уйму увлекательных сюжетов, создавший прекрасные и загадочные миры, отличающиеся мрачностью и таинственностью.', '2025-08-19 13:30:00');
